import pandas as pd
import ast

users = pd.read_parquet('data/processed/users.parquet')
mapping_df = pd.read_csv('docs/interests_mapping.csv')
mapping_dict = dict(zip(mapping_df.iloc[:, 0], mapping_df.iloc[:, 1]))

def get_tags(raw):
    if raw is None or pd.isna(raw):
        return set()
    try:
        return set(mapping_dict.get(t, t) for t in ast.literal_eval(raw))
    except Exception:
        return set()

user_tags = users['interests'].apply(get_tags)

tag_to_field_value = {
    'smoker': ('smoking', 'Y'),
    'non_smoker': ('smoking', 'N'),
    'early_bird': ('daily_routine', 'EB'),
    'night_owl': ('daily_routine', 'NO'),
    'loves_cleanliness': ('cleanliness', 'VT'),
    'works_remote': ('work_from_home', 'Y'),
    'quiet_evenings': ('noise_level', 'Q'),
    'silence_after_22': ('noise_level', 'Q'),
    'likes_calm': ('noise_level', 'Q'),
    'peace_and_quite': ('noise_level', 'Q'),
    'likes_parties': ('noise_level', 'P'),
    'music_nonstop': ('noise_level', 'P'),
}

for field in ['smoking', 'daily_routine', 'cleanliness', 'work_from_home', 'noise_level']:
    raw_missing = users[field].isna().sum()
    filled = users[field].copy()
    for tag, (f, val) in tag_to_field_value.items():
        if f == field:
            mask = filled.isna() & user_tags.apply(lambda s: tag in s)
            filled[mask] = val
    new_missing = filled.isna().sum()
    print(f'{field}: missing before = {raw_missing} ({raw_missing/len(users):.1%}), missing after D13 = {new_missing} ({new_missing/len(users):.1%})')
